 "add_facts": [],
 "corrections": [
  {
   "old_memory_id": "1000043",
   "new_content": "As of 2025-11-06, feature-flags is owned by the Ember team, which the Atlas team owned until then.",
   "entities": ["feature-flags", "Ember team", "Atlas team"],
   "kind": "decision",
   "confidence": 1,
   "evidence": "feature-flags belongs to team Ember starting today. Thanks to team Atlas for running it until now."
  }
 ],
 "add_relations": [
  {
   "src": "Ember team",
   "dst": "feature-flags",
   "rel_kind": "owns",
   "evidence": "feature-flags belongs to team Ember starting today"
  }
 ],
 "remove_relations": [
  {
   "src": "Atlas team",
   "dst": "feature-flags",
   "rel_kind": "owns",
   "evidence": "Thanks to team Atlas for running it until now"
  }
 ],
 "entity_aliases": [
  {
   "name": "team Ember",
   "canonical": "Ember team",
   "evidence": "feature-flags belongs to team Ember starting today"
  }
 ]
}

